<template><view class="page"><nav-bar title="选择试题" :showBack="true" placeholder/>
  <view class="summary"><view><text class="name">{{paper.name}}</text><text class="meta">已选 {{paper.questionCount||0}} 题 · {{paper.totalScore||0}} 分</text></view><view class="selected" @click="viewSelected">查看已选</view></view>
  <view class="tabs"><view v-for="t in tabs" :key="t.key" :class="['tab',source===t.key?'active':'']" @click="switchSource(t.key)">{{t.name}}</view></view>
  <view class="filters"><view class="search"><text>⌕</text><input v-model="keyword" placeholder="搜索题目或知识点" confirm-type="search" @confirm="loadQuestions"/></view><picker :range="types" @change="type=types[$event.detail.value];loadQuestions()"><view class="chip">{{type||'题型'}}⌄</view></picker><picker :range="difficulties" @change="difficulty=difficulties[$event.detail.value];loadQuestions()"><view class="chip">{{difficulty||'难度'}}⌄</view></picker></view>
  <scroll-view v-if="source!=='favorite'&&!bankId" scroll-y class="list"><view v-for="b in banks" :key="b.id" class="bank-card" @click="openBank(b)"><view><text class="bank-name">{{b.name}}</text><text class="bank-desc">{{b.description||'暂无说明'}}</text></view><text class="count">{{b.questionCount||0}}题 ›</text></view><view v-if="!loading&&!banks.length" class="empty">暂无题库</view></scroll-view>
  <scroll-view v-else scroll-y class="list" @scrolltolower="noop"><view v-for="q in questions" :key="q.id" :class="['question-card',q.selected?'chosen':'']"><view class="tags"><text>{{q.questionType}}</text><text>{{q.difficulty}}</text><text>{{q.chapter}}</text></view><text class="content">{{q.content}}</text><text class="knowledge">{{q.knowledgePoint||q.bankName}}</text><view class="actions"><text @click="toggleFavorite(q)">{{q.favorited?'★ 已收藏':'☆ 收藏'}}</text><button :class="q.selected?'added':''" :disabled="q.selected||busyId===q.id" @click="add(q)">{{q.selected?'已加入':'加入试卷'}}</button></view></view><view v-if="!loading&&!questions.length" class="empty">没有符合条件的题目</view></scroll-view>
  <view class="bottom"><text>已选 {{paper.questionCount||0}} 题</text><button @click="viewSelected">查看已选题目</button></view>
</view></template>
<script>import NavBar from '@/components/nav-bar/nav-bar.vue';import{getPaper,listPaperBanks,listQuestions,listFavoriteQuestions,addPaperQuestion,favoriteQuestion,unfavoriteQuestion}from'@/api/paper.js';export default{components:{NavBar},data(){return{paperId:null,paper:{},source:'public',bankId:null,banks:[],questions:[],keyword:'',type:'',difficulty:'',types:['','单选题','多选题','判断题','填空题','简答题','计算题','编程题'],difficulties:['','简单','中等','困难'],tabs:[{key:'public',name:'共有题库'},{key:'private',name:'私有题库'},{key:'favorite',name:'收藏夹'}],loading:false,busyId:null}},onLoad(q){this.paperId=q.paperId;this.source=q.source||'public'},onShow(){this.loadPaper();this.loadSource()},methods:{async loadPaper(){const r=await getPaper(this.paperId);this.paper=r.data||{}},async loadSource(){this.bankId=null;this.questions=[];if(this.source==='favorite')return this.loadQuestions();this.loading=true;try{const r=await listPaperBanks({visibility:this.source,keyword:this.keyword});this.banks=r.data||[]}finally{this.loading=false}},switchSource(s){this.source=s;this.loadSource()},openBank(b){this.bankId=b.id;this.loadQuestions()},async loadQuestions(){this.loading=true;try{const p={paperId:this.paperId,keyword:this.keyword,type:this.type,difficulty:this.difficulty};const r=this.source==='favorite'?await listFavoriteQuestions(p):await listQuestions(this.bankId,p);this.questions=r.data||[]}finally{this.loading=false}},async add(q){this.busyId=q.id;try{const r=await addPaperQuestion(this.paperId,{questionId:q.id,score:5,sourceType:this.source,sourceId:q.bankId});this.paper=r.data;q.selected=true;uni.showToast({title:'已加入试卷',icon:'success'})}finally{this.busyId=null}},async toggleFavorite(q){if(q.favorited)await unfavoriteQuestion(q.id);else await favoriteQuestion(q.id);q.favorited=!q.favorited;uni.showToast({title:q.favorited?'收藏成功':'已取消收藏',icon:'none'})},viewSelected(){uni.navigateTo({url:`/subpackage_ai/paperSelected/paperSelected?paperId=${this.paperId}`})},noop(){}}}</script>
<style scoped lang="scss">.page{min-height:100vh;background:#f5f8fc;padding-bottom:120rpx}.summary{margin:20rpx 24rpx;padding:25rpx;background:linear-gradient(135deg,#eef5ff,#fff);border-radius:20rpx;display:flex;justify-content:space-between;align-items:center}.name{display:block;font-weight:700;color:#26364f;font-size:29rpx}.meta{display:block;color:#76839a;font-size:23rpx;margin-top:8rpx}.selected{color:#4775e5;font-size:24rpx}.tabs{display:flex;background:#fff;padding:0 24rpx}.tab{flex:1;text-align:center;padding:22rpx 0;color:#7d899a}.active{color:#4775e5;font-weight:700;border-bottom:4rpx solid #4775e5}.filters{display:flex;gap:12rpx;padding:18rpx 24rpx}.search{flex:1;background:#fff;border-radius:30rpx;padding:12rpx 18rpx;display:flex}.search input{font-size:24rpx;margin-left:8rpx}.chip{background:#fff;border-radius:28rpx;padding:13rpx 18rpx;font-size:23rpx;color:#58667c}.list{height:calc(100vh - 410rpx);padding:0 24rpx;box-sizing:border-box}.bank-card,.question-card{background:#fff;border-radius:18rpx;padding:24rpx;margin-bottom:14rpx}.bank-card{display:flex;justify-content:space-between;align-items:center}.bank-name{display:block;color:#26364f;font-weight:600}.bank-desc{display:block;color:#9aa5b5;font-size:22rpx;margin-top:8rpx}.count{font-size:23rpx;color:#6483d7}.chosen{border:2rpx solid #82a4fa;background:#f7faff}.tags text{background:#eef4ff;color:#5876bc;padding:6rpx 12rpx;border-radius:10rpx;font-size:20rpx;margin-right:8rpx}.content{display:block;font-size:27rpx;line-height:1.6;color:#26364f;margin:18rpx 0}.knowledge{font-size:22rpx;color:#9ba5b4}.actions{display:flex;justify-content:space-between;align-items:center;color:#e2a034;font-size:23rpx;margin-top:18rpx}.actions button{margin:0;background:#4d78e8;color:#fff;border-radius:30rpx;font-size:23rpx;line-height:56rpx}.actions .added{background:#eaf0fc;color:#7790c6}.bottom{position:fixed;left:0;right:0;bottom:0;background:#fff;padding:16rpx 24rpx calc(16rpx + env(safe-area-inset-bottom));display:flex;justify-content:space-between;align-items:center;box-shadow:0 -4rpx 20rpx rgba(30,50,90,.08)}.bottom button{margin:0;background:#4d78e8;color:#fff;border-radius:36rpx;font-size:25rpx}.empty{text-align:center;color:#a0aaba;padding:100rpx 0}</style>
